contract MyComplexContract {
    address public owner;
    mapping(address => uint256) public balances;

    event LogTransaction(address indexed _from, address indexed _to, uint256 _value);

    constructor() public {
        owner = msg.sender;
    }

    function deposit() public payable {
        require(msg.sender == owner, "Only the contract owner can deposit.");
        balances[msg.sender] += msg.value;
        emit LogTransaction(msg.sender, address(this), msg.value);
    }

    function withdraw(uint256 _amount) public {
        require(balances[msg.sender] >= _amount, "Insufficient balance.");
        balances[msg.sender] -= _amount;
        msg.sender.transfer(_amount);
        emit LogTransaction(msg.sender, address(0x0), _amount);
    }

    function transfer(address _to, uint256 _amount) public {
        require(balances[msg.sender] >= _amount, "Insufficient balance.");
        balances[msg.sender] -= _amount;
        balances[_to] += _amount;
        emit LogTransaction(msg.sender, _to, _amount);
    }

    function balanceOf(address _address) public view returns (uint256) {
        return balances[_address];
    }
}
```

This smart contract includes functions for depositing, withdrawing, and transferring Ether, as well as checking the balance of an address. It also logs transactions using an event. Keep in mind that this is a simple example, and a real-world complex smart contract may require additional functions, events, and state variables to meet specific requirements.

For more information on writing smart contracts, I recommend checking out the Solidity documentation: https://docs.soliditylang.org/en/v0.8.0/

