    int var1 = 5;
    int var2 = 10;
    int var3 = 15;

    for (int i = 1; i <= 3; ++i) {
        int& current_var = (i == 1) ? var1 : (i == 2) ? var2 : var3;
        std::cout << "The value of var" << i << " is: " << current_var << std::endl;
